const report={createdAt:new Date().toISOString(),theme:THEME,route:ROOT,desktop:{},mobile:{},interactions:[],pageSizes:[],errors:[]};

function diag(page){const x={pageErrors:[],consoleErrors:[],failed:[],http:[]};page.on('pageerror',e=>x.pageErrors.push(String(e)));page.on('console',m=>{if(m.type()==='error')x.consoleErrors.push(m.text())});page.on('requestfailed',r=>x.failed.push({url:r.url(),error:r.failure()?.errorText||''}));page.on('response',r=>{if(r.status()>=400)x.http.push({status:r.status(),url:r.url()})});return x}
async function ready(page){await page.waitForLoadState('domcontentloaded',{timeout:90000});await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:60000});await page.waitForSelector('#MainContent .sq-refine-v3-sidebar',{state:'visible',timeout:20000});await sleep(900)}
async function resetScroll(page){for(let i=0;i<3;i++){await page.evaluate(()=>{const s=document.querySelector('.page-wrapper');if(s){s.scrollTop=0;s.scrollTo(0,0)}window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0});await sleep(250)}return page.evaluate(()=>document.querySelector('.page-wrapper')?.scrollTop||window.scrollY)}
async function scrollToFrac(page,f){return page.evaluate(fr=>{const s=document.querySelector('.page-wrapper');const h=(s?.scrollHeight||document.documentElement.scrollHeight)-(s?.clientHeight||innerHeight);const y=Math.max(0,Math.round(h*fr));if(s)s.scrollTo(0,y);else window.scrollTo(0,y);return y},f)}
async function snap(page,name){await page.screenshot({path:path.join(OUT,name),fullPage:false})}
async function state(page){return page.evaluate(()=>{
 const main=document.querySelector('#MainContent'), side=main?.querySelector('.sq-refine-v3-sidebar'), head=side?.querySelector('.sq-refine-v3-sidebar__title'), results=main?.querySelector('.sq-refine-v3-results'), sc=document.querySelector('.page-wrapper');
 const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0&&r.width>1&&r.height>1&&r.bottom>0&&r.top<innerHeight};
 const grids=[...main.querySelectorAll('.product-grid')].map((g,i)=>{const r=g.getBoundingClientRect(),cs=getComputedStyle(g),links=g.querySelectorAll('a[href*="/products/"]').length;return{index:i,inV3:!!results?.contains(g),links,display:cs.display,visibility:cs.visibility,rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)},visible:links>0&&cs.display!=='none'&&cs.visibility!=='hidden'&&r.width>1&&r.height>1}});
 const authoritative=grids.find(g=>g.inV3), cards=results?[...results.querySelectorAll('.product-grid > .product-grid__item')].filter(x=>x.querySelector('a[href*="/products/"]')):[];const rects=cards.slice(0,12).map(x=>{const r=x.getBoundingClientRect();return{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)}}), y=rects[0]?.y;
 const groups=side?[...side.querySelectorAll(':scope > details.sq-refine-v3-group')].map(d=>({label:(d.querySelector(':scope>summary')?.textContent||'').trim().replace(/\s+/g,' '),choices:[...d.querySelectorAll('.sq-refine-v3-choice')].map(r=>{const i=r.querySelector('input'),sp=r.querySelector('span');return{label:(sp?.textContent||'').trim().replace(/\s+/g,' '),kind:i?.dataset.kind||'',target:i?.dataset.target||'',name:i?.dataset.filterName||i?.dataset.sqPolishParam||'',value:i?.dataset.filterValue||i?.dataset.sqPolishValue||i?.value||'',checked:!!i?.checked}})})):[];
 const ps=[...main.querySelectorAll('.sq-refine-v3-page-size label')].map(l=>{const i=l.querySelector('input'),sp=l.querySelector('span'),r=sp?.getBoundingClientRect(),cs=sp?getComputedStyle(sp):null;return{value:i?.value||'',checked:!!i?.checked,label:(sp?.textContent||'').trim(),visible:!!sp&&cs.display!=='none'&&cs.visibility!=='hidden'&&Number(cs.opacity||1)>0&&(r?.width||0)>1&&(r?.height||0)>1}});
 const imgs=cards.slice(0,50).map(c=>{const i=c.querySelector('img');return i?{src:i.currentSrc||i.src,complete:i.complete,nw:i.naturalWidth,nh:i.naturalHeight}:null});
 const sr=side?.getBoundingClientRect(),hr=head?.getBoundingClientRect();
 return{url:location.href,ready:main?.dataset.sqRefineV3Ready||'',error:main?.dataset.sqRefineV3Error||'',scrollTop:sc?.scrollTop||scrollY,scrollHeight:sc?.scrollHeight||document.documentElement.scrollHeight,clientHeight:sc?.clientHeight||innerHeight,sidebar:side?{position:getComputedStyle(side).position,rect:{x:Math.round(sr.x),y:Math.round(sr.y),w:Math.round(sr.width),h:Math.round(sr.height)},viewportVisible:vis(side)}:null,header:head?{text:head.textContent.trim(),bg:getComputedStyle(head).backgroundColor,fg:getComputedStyle(head).color,rightGap:Math.round((sr.right-hr.right)*10)/10,viewportVisible:vis(head)}:null,grids,authoritative,cards:cards.length,firstRow:rects.filter(r=>Math.abs(r.y-y)<=3).length,cardWidth:rects[0]?.w||0,groups,pageSizes:ps,images:imgs,horizontalOverflow:(sc?.scrollWidth||document.documentElement.scrollWidth)>(sc?.clientWidth||innerWidth)+2};
})}
function categoryIssues(s){const g=s.groups.find(x=>x.label==='Shop by Category'),out=[];if(!g)return['missing Shop by Category'];if(g.choices.length!==9)out.push(`category count ${g.choices.length}`);EXPECT.forEach(([label,h],i)=>{const c=g.choices[i];if(!c)out.push(`missing ${label}`);else{if(c.label!==label)out.push(`wrong category label ${i+1}: ${c.label}`);if(!String(c.target).startsWith(`/collections/${h}?`))out.push(`${label} bad target ${c.target}`);try{const u=new URL(c.target,BASE);if(u.searchParams.get('sq_root')!=='accessories-gifts-collectibles')out.push(`${label} missing sq_root`)}catch{out.push(`${label} invalid target`)}}});if(g.choices.some(c=>/\/collections\/all(?:\?|$)/.test(c.target)))out.push('generic /collections/all target');return out}
function baseIssues(s,mobile=false){const out=[];if(s.ready!=='true'||s.error)out.push(`V3 not ready: ${s.error||s.ready}`);if(!s.sidebar)out.push('sidebar missing');if(s.header?.text!=='REFINE PRODUCTS')out.push(`header ${s.header?.text}`);if(s.header?.bg!=='rgb(8, 40, 63)'||s.header?.fg!=='rgb(255, 255, 255)')out.push('header colors wrong');if((s.header?.rightGap??99)>1.5)out.push(`header right gap ${s.header?.rightGap}`);if(s.horizontalOverflow)out.push('horizontal overflow');const visibleProductGrids=s.grids.filter(g=>g.visible);if(visibleProductGrids.length!==1)out.push(`visible product grids ${visibleProductGrids.length}`);if(!visibleProductGrids[0]?.inV3)out.push('visible product grid not authoritative V3');if(s.cards<1)out.push('no V3 cards');if(mobile){if(s.sidebar?.position==='sticky')out.push('mobile sidebar sticky');if(s.cards&&s.firstRow!==2)out.push(`mobile columns ${s.firstRow}`)}else{if(s.sidebar?.position!=='sticky')out.push(`desktop sidebar ${s.sidebar?.position}`);if(s.cards&&s.firstRow!==3)out.push(`desktop columns ${s.firstRow}`);if(s.cardWidth<250)out.push(`desktop card width ${s.cardWidth}`)}if(s.pageSizes.map(x=>x.value).join(',')!=='50,100,250')out.push('page-size choices wrong');s.pageSizes.forEach(x=>{if(!x.visible||x.label!==x.value)out.push(`page-size ${x.value} label hidden`)});return out}
async function sweep(page,prefix,mobile=false){const points=[];for(const [name,f] of [['top',0],['quarter',.25],['middle',.5],['three-quarter',.75],['bottom',1]]){await scrollToFrac(page,f);await sleep(800);const s=await state(page);points.push({name,...s});await snap(page,`${prefix}-${name}.png`)}await resetScroll(page);const issues=[];for(const p of points){const visibleAuth=p.authoritative&&p.authoritative.rect.y<p.clientHeight&&p.authoritative.rect.y+p.authoritative.rect.h>0;if(!mobile&&visibleAuth&&!p.sidebar?.viewportVisible)issues.push(`${p.name}: sidebar not visible while authoritative grid is visible`);const vg=p.grids.filter(g=>g.visible);if(vg.length!==1||!vg[0]?.inV3)issues.push(`${p.name}: ${vg.length} visible product grids / authoritative=${vg[0]?.inV3||false}`)}return{points,issues}}
async function imageGate(page){const cards=page.locator('#MainContent .sq-refine-v3-results .product-grid > .product-grid__item');const n=Math.min(await cards.count(),50);for(let i=0;i<n;i+=3){await cards.nth(i).scrollIntoViewIfNeeded().catch(()=>{});await sleep(140)}await sleep(900);const s=await state(page);await resetScroll(page);const broken=s.images.filter(x=>!x||!x.complete||!x.nw||!x.nh);return{count:broken.length,broken}}
async function clickFilter(page,label,wanted){await page.goto(startUrl(),{waitUntil:'domcontentloaded',timeout:90000});await ready(page);const det=page.locator('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group').filter({has:page.locator(':scope>summary',{hasText:label})}).first();const r={group:label,pass:true};try{if(!await det.count())throw new Error('group missing');if(await det.getAttribute('open')===null)await det.locator(':scope>summary').click();const inp=wanted?det.locator('.sq-refine-v3-choice',{hasText:wanted}).locator('input').first():det.locator('input:not(:checked)').first();if(!await inp.count())throw new Error('choice missing');r.meta=await inp.evaluate(i=>({label:(i.closest('label')?.querySelector('span')?.textContent||'').trim(),name:i.dataset.filterName||i.dataset.sqPolishParam||'',value:i.dataset.filterValue||i.dataset.sqPolishValue||i.value||''}));r.before=page.url();await Promise.allSettled([page.waitForURL(u=>u.toString()!==r.before,{timeout:15000}),inp.click({force:true})]);await sleep(500);r.after=page.url();r.dataset=await page.evaluate(()=>({ready:document.querySelector('#MainContent')?.dataset.sqRefineV3Ready||'',error:document.querySelector('#MainContent')?.dataset.sqRefineV3Error||''}));if(r.after===r.before)throw new Error('URL did not change');const u=new URL(r.after);if(!u.searchParams.getAll(r.meta.name).includes(r.meta.value))throw new Error(`URL missing ${r.meta.name}=${r.meta.value}`);await ready(page);const after=await state(page);if(after.cards<1)throw new Error('zero products');await snap(page,`desktop-${label.toLowerCase().replace(/[^a-z0-9]+/g,'-')}.png`);await page.reload({waitUntil:'domcontentloaded',timeout:90000});await ready(page);const persisted=await page.evaluate(m=>[...document.querySelectorAll('#MainContent .sq-refine-v3-sidebar input:checked')].some(i=>(i.dataset.filterName||i.dataset.sqPolishParam)===m.name&&(i.dataset.filterValue||i.dataset.sqPolishValue||i.value)===m.value),r.meta);r.refreshPersisted=persisted;if(!persisted)throw new Error('not persisted after refresh');await page.goBack({waitUntil:'domcontentloaded',timeout:90000});await ready(page);r.back=page.url();if(r.back!==r.before)throw new Error(`Back did not restore root: ${r.back}`)}catch(e){r.pass=false;r.error=String(e);r.after=page.url();r.dataset=await page.evaluate(()=>({ready:document.querySelector('#MainContent')?.dataset.sqRefineV3Ready||'',error:document.querySelector('#MainContent')?.dataset.sqRefineV3Error||''})).catch(()=>null)}return r}
async function childGate(page){await page.goto(startUrl(),{waitUntil:'domcontentloaded',timeout:90000});await ready(page);const det=page.locator('#MainContent .sq-refine-v3-sidebar details.sq-refine-v3-group').filter({has:page.locator(':scope>summary',{hasText:'Shop by Category'})}).first();if(await det.getAttribute('open')===null)await det.locator(':scope>summary').click();await Promise.allSettled([page.waitForURL(/challenge-coins-display-holders/,{timeout:15000}),det.locator('input').first().click({force:true})]);await ready(page);const s=await state(page);const issues=categoryIssues(s);return{pass:page.url().includes('/collections/challenge-coins-display-holders')&&issues.length===0,url:page.url(),issues,state:s}}
async function pageSizes(page){const out=[];for(const n of [50,100,250]){const u=new URL(startUrl());u.searchParams.set('sq_per_page',String(n));u.searchParams.set('sq_view_page','1');await page.goto(u.toString(),{waitUntil:'domcontentloaded',timeout:90000});await ready(page);const s=await state(page);out.push({size:n,cards:s.cards,checked:s.pageSizes.find(x=>x.value===String(n))?.checked===true,labels:s.pageSizes.every(x=>x.visible&&x.label===x.value),pass:s.cards>0&&s.cards<=n&&s.pageSizes.find(x=>x.value===String(n))?.checked===true&&s.pageSizes.every(x=>x.visible&&x.label===x.value)})}return out}

const browser=await chromium.launch({headless:true});let fatal=null;
try{
 const dc=await browser.newContext({viewport:{width:1440,height:1000},recordVideo:{dir:path.join(OUT,'desktop-video'),size:{width:960,height:666}}});const dp=await dc.newPage(),dd=diag(dp),dv=dp.video();await dp.goto(startUrl(),{waitUntil:'domcontentloaded',timeout:90000});await ready(dp);await resetScroll(dp);report.desktop.initial=await state(dp);report.desktop.categoryIssues=categoryIssues(report.desktop.initial);report.desktop.baseIssues=baseIssues(report.desktop.initial,false);report.desktop.sweep=await sweep(dp,'desktop',false);report.desktop.images=await imageGate(dp);report.child=await childGate(dp);for(const x of [['Shop by Type',null],['Shop by Manufacturers',null],['Availability','In stock']])report.interactions.push(await clickFilter(dp,...x));report.pageSizes=await pageSizes(dp);report.desktop.diag=dd;await dc.close();await fs.copyFile(await dv.path(),path.join(OUT,'desktop-audit.webm'));
 const mc=await browser.newContext({viewport:{width:390,height:844},recordVideo:{dir:path.join(OUT,'mobile-video'),size:{width:390,height:844}}});const mp=await mc.newPage(),md=diag(mp),mv=mp.video();await mp.goto(startUrl(),{waitUntil:'domcontentloaded',timeout:90000});await ready(mp);await resetScroll(mp);report.mobile.initial=await state(mp);report.mobile.categoryIssues=categoryIssues(report.mobile.initial);report.mobile.baseIssues=baseIssues(report.mobile.initial,true);report.mobile.sweep=await sweep(mp,'mobile',true);report.mobile.images=await imageGate(mp);report.mobile.diag=md;await mc.close();await fs.copyFile(await mv.path(),path.join(OUT,'mobile-audit.webm'));
}catch(e){fatal=String(e);report.errors.push(fatal)}finally{await browser.close()}
report.checks={desktopBase:report.desktop.baseIssues?.length===0,desktopCategory:report.desktop.categoryIssues?.length===0,desktopSweep:report.desktop.sweep?.issues?.length===0,desktopImages:report.desktop.images?.count===0,mobileBase:report.mobile.baseIssues?.length===0,mobileCategory:report.mobile.categoryIssues?.length===0,mobileSweep:report.mobile.sweep?.issues?.length===0,mobileImages:report.mobile.images?.count===0,childCategory:report.child?.pass===true,interactions:report.interactions.length===3&&report.interactions.every(x=>x.pass),pageSizes:report.pageSizes.length===3&&report.pageSizes.every(x=>x.pass),desktopRuntime:(report.desktop.diag?.pageErrors.length||0)===0,mobileRuntime:(report.mobile.diag?.pageErrors.length||0)===0};report.pass=!fatal&&Object.values(report.checks).every(Boolean);await fs.writeFile(path.join(OUT,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({pass:report.pass,checks:report.checks,desktopBase:report.desktop.baseIssues,desktopCategory:report.desktop.categoryIssues,desktopSweep:report.desktop.sweep?.issues,mobileBase:report.mobile.baseIssues,mobileCategory:report.mobile.categoryIssues,mobileSweep:report.mobile.sweep?.issues,child:report.child&&{pass:report.child.pass,url:report.child.url,issues:report.child.issues},interactions:report.interactions,pageSizes:report.pageSizes,fatal},null,2));if(!report.pass)process.exitCode=1;
